package com.cpf.integration.fixedlength;import java.nio.*;import java.nio.charset.*;import java.util.*;
public final class CpfFixedLengthCodec {private final CpfFixedLengthLayout layout;public CpfFixedLengthCodec(CpfFixedLengthLayout l){layout=l;}
 public byte[] encode(Map<String,String> values){char[] record=new char[layout.recordLength()];Arrays.fill(record,' ');for(var f:layout.fields()){String v=values.get(f.name());if((v==null||v.isEmpty())&&f.required())throw new IllegalArgumentException("required field: "+f.name());v=v==null?"":v;if(v.length()>f.length())throw new IllegalArgumentException("field overflow: "+f.name());int start=f.alignment()==CpfFixedLengthField.Alignment.LEFT?f.offset():f.offset()+f.length()-v.length();Arrays.fill(record,f.offset(),f.offset()+f.length(),f.pad());v.getChars(0,v.length(),record,start);}try{ByteBuffer buffer=strictEncoder().encode(CharBuffer.wrap(record));byte[] output=new byte[buffer.remaining()];buffer.get(output);return output;}catch(CharacterCodingException ex){throw new IllegalArgumentException("record contains unmappable characters",ex);}}
 public Map<String,String> decode(byte[] bytes){String value;try{value=strictDecoder().decode(ByteBuffer.wrap(bytes)).toString();}catch(CharacterCodingException ex){throw new IllegalArgumentException("record contains malformed bytes",ex);}if(value.length()!=layout.recordLength())throw new IllegalArgumentException("record length mismatch");Map<String,String> result=new LinkedHashMap<>();for(var f:layout.fields()){String raw=value.substring(f.offset(),f.offset()+f.length());result.put(f.name(),strip(raw,f.pad(),f.alignment()));}return Map.copyOf(result);}
 private CharsetEncoder strictEncoder(){return layout.charset().newEncoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT);}
 private CharsetDecoder strictDecoder(){return layout.charset().newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT);}
 private static String strip(String v,char pad,CpfFixedLengthField.Alignment a){int s=0,e=v.length();if(a==CpfFixedLengthField.Alignment.RIGHT)while(s<e&&v.charAt(s)==pad)s++;else while(e>s&&v.charAt(e-1)==pad)e--;return v.substring(s,e);}}
